export declare const styles = "\n  :host {\n    \n  --_dot: var(--dot-color, rgba(13, 19, 16, 0.18));\n  --_active: var(--dot-active-color, #1d8049);\n\n    position: relative;\n    display: block;\n  }\n\n  :host([theme='dark']) {\n    \n  --_dot: var(--dot-color, rgba(233, 238, 234, 0.16));\n  --_active: var(--dot-active-color, #43c97e);\n\n  }\n\n  @media (prefers-color-scheme: dark) {\n    :host(:not([theme='light'])) {\n      \n  --_dot: var(--dot-color, rgba(233, 238, 234, 0.16));\n  --_active: var(--dot-active-color, #43c97e);\n\n    }\n  }\n\n  :host([hidden]) {\n    display: none;\n  }\n\n  canvas {\n    position: absolute;\n    inset: 0;\n    display: block;\n    width: 100%;\n    height: 100%;\n    pointer-events: none;\n  }\n\n  .content {\n    position: relative;\n  }\n\n  .probe {\n    display: none;\n  }\n\n  .probe-dot {\n    color: var(--_dot);\n  }\n\n  .probe-active {\n    color: var(--_active);\n  }\n";
